import React from "react";
import "./BodyLayout.css";
import Navbar from "../Navbar/Navbar";
import LeftSidebar from "../LeftSidebar/LeftSidebar";
import RightSidebar from "../RightSidebar/RightSidebar";
import ContentContainer from "../ContentContainer/ContentContainer";
import { CarouselProvider } from "../Carousel/CarouselContext";
import { CallendarButtonsProvider, SlideOutButtonsProvider } from "../LeftSidebar/CallendarrButton/CallendarButtonsContext";

const BodyLayout = () => {
  return (
    <>
      <SlideOutButtonsProvider>

      </SlideOutButtonsProvider>
        <div className="body-container body-grid">
          <Navbar />
          <CarouselProvider>
            <LeftSidebar />
            <RightSidebar />
            <ContentContainer />
          </CarouselProvider>
        </div>
    </>
  );
};

export default BodyLayout;
